    assert Arrays.equals(solution.minCost(new int[]{3, 3}, new int[]{0, 0}, new int[]{10, 20, 30, 40}, new int[]{5, 15, 25, 35}), 105);
    assert Arrays.equals(solution.minCost(new int[]{1, 0}, new int[]{2, 3}, new int[]{5, 4, 3}, new int[]{8, 2, 6, 7}), 18);
