    assert Arrays.equals(solution.minCost(new int[]{1, 1}, new int[]{1, 1}, new int[]{1, 2, 3}, new int[]{4, 5, 6}), 0);
    assert Arrays.equals(solution.minCost(new int[]{2, 2}, new int[]{0, 0}, new int[]{1, 1, 1}, new int[]{1, 1, 1}), 4);
    assert Arrays.equals(solution.minCost(new int[]{0, 1}, new int[]{2, 1}, new int[]{3, 2, 1}, new int[]{4, 5}), 3);
